package com.yeyamo_mobile.api.referral_service.application;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;
class HashingServiceTest{private final HashingService hashing=new HashingService();@Test void normalizesEmailBeforeHashing(){assertEquals(hashing.email("Alice@Example.COM"),hashing.email(" alice@example.com "));}@Test void hashesDeviceWithoutExposingValue(){String hash=hashing.fingerprint("device-123");assertEquals(64,hash.length());assertFalse(hash.contains("device"));}@Test void acceptsMissingFingerprint(){assertNull(hashing.fingerprint(null));}}
